/**
 * Instance based version of timing
 * To allow hybrid timing events and for multiple
 * clocks to run at different rates
 */
import {
    CMD_START, CMD_STOP, CMD_UPDATE,
    EVENT_READY, EVENT_STARTING, EVENT_STOPPING, EVENT_TICK
} from './timer-event-types'

import { tapTempoQuick } from './tap-tempo'
import { Ticks, MICROSECONDS_PER_MINUTE, SECONDS_PER_MINUTE } from './time-utils'
import type { AudioTickTiming, SyncMode, TimerSyncOptions, TimerSyncMetadata, WorkerWrapper } from './timer-interfaces'

import Epoch from './epoch'
import { TimerOptions, DEFAULT_SYNC_OPTIONS, DEFAULT_TIMER_OPTIONS } from './timer-options'

import { AudioContextWorkerWrapper, RollingTimeWorkerWrapper, SetIntervalWorkerWrapper, SetTimeoutWorkerWrapper } from './timer-worker-types'
import { TIMER_TYPE_AUDIO_CONTEXT, TIMER_TYPE_AUDIO_WORKLET, TIMER_TYPE_ELASTIC_AUDIO_WORKLET, TIMER_TYPE_ROLLING, TIMER_TYPE_SET_INTERVAL, TIMER_TYPE_SET_TIMEOUT, TIMER_TYPES, isValidTimerType, isWorkletTimerType, type TimerType } from './timer-types'

import type { ITimerControl, TimingHandler, TimerCallbackEvent } from './timer-interfaces'
export type { ITimerControl, TimingHandler, TimerCallbackEvent }

export const MAX_BARS_ALLOWED = 32

const NETWORK_SYNC_MODES: readonly SyncMode[] = ['network-leader', 'network-follower'] as const

const hasOwn = <T extends object>(value: T, key: keyof any): boolean =>
    Object.prototype.hasOwnProperty.call(value, key)

const normalizeSyncOptions = (options: TimerOptions, fallback: TimerSyncOptions = DEFAULT_SYNC_OPTIONS): TimerSyncOptions => {
    if (hasOwn(options, 'sync') && options.sync) {
        return { ...DEFAULT_SYNC_OPTIONS, ...options.sync } as TimerSyncOptions
    }

    if (hasOwn(options, 'synch')) {
        return options.synch === false
        ? { mode: 'off', join: DEFAULT_SYNC_OPTIONS.join, beatsPerBar: DEFAULT_SYNC_OPTIONS.beatsPerBar }
        : { ...DEFAULT_SYNC_OPTIONS }
    }

    return { ...fallback }
}

// Re-export interfaces for external use

/**
 * Resolve a timer type string to its corresponding Worker constructor
 * @param timerType Timer type ID string (e.g., TIMER_TYPE_AUDIO_CONTEXT)
 * @returns Worker constructor or null if not found
 * @example
 * const workerClass = resolveTimerType(TIMER_TYPE_AUDIO_CONTEXT)
 */
export const resolveTimerType = (timerType: TimerType | string): WorkerWrapper | null => {
    if (!isValidTimerType(timerType)) {
        return null
    }

    switch (timerType) {
        case TIMER_TYPE_AUDIO_CONTEXT:
            return AudioContextWorkerWrapper
        case TIMER_TYPE_ROLLING:
            return RollingTimeWorkerWrapper
        case TIMER_TYPE_SET_INTERVAL:
            return SetIntervalWorkerWrapper
        case TIMER_TYPE_SET_TIMEOUT:
            return SetTimeoutWorkerWrapper
        case TIMER_TYPE_AUDIO_WORKLET:
        case TIMER_TYPE_ELASTIC_AUDIO_WORKLET:
            // Audio worklet is handled specially, return null here
            return null
        default:
            return null
    }
}

/**
 * Simple boolean test to work out if this is a Worklet
 * or a simple Worker file (not very smart - may break in future)
 * @param file
 * @returns boolean indicating if file is a worklet
 */
export const isFileWorklet = (file: string | TimerType): boolean => {

    const normalized = typeof file === 'string' ? file.toLowerCase() : file

    if (typeof file === "function") {
        return false
    }
    if (typeof normalized === 'string' && normalized === TIMER_TYPE_AUDIO_WORKLET) {
        return true
    }
    if (typeof normalized === 'string' && normalized.indexOf("orklet") > -1) {
        return true
    }
    if (typeof normalized === 'string' && normalized.indexOf("data:text/javascript;base64,") > -1) {
        return true
    }
    return false
}


export default class Timer {

    #pausedAt: number | null = null
    #resumeElapsed: number = 0
    #workerElapsedOffset: number = 0

    startTime: number = -1
    period: number = 100
    
    #expectedAtTempoChange: number = 0
    #intervalsAtTempoChange: number = 0
    #lastTickIntervals: number = 0
    #transportAnchorExpected: number = 0
    #transportAnchorClockTime: number = -1
    #clockTimeToElapsedScale: number = 0

    // for time formatting...
    currentBar: number = 0

    divisions: number = 24	// 24 quarter notes in a bar
    bars: number = 16		// 16 bars in a measure
    swingOffset: number = 0	// ratio from 0 -> 1 of one subdivision delay applied to every second beat

    divisionsElapsed: number = 0
    totalBarsElapsed: number = 0

    lastRecordedTime: number = 0
    lastRecordedExternalTime: number = 0

    #running: boolean = false
    #active: boolean = false
    #bypassed: boolean = false
    isCompatible: boolean = false

    timingWorkHandler: TimingHandler = null
    audioContext?: AudioContext

    #options:TimerOptions

    // Epoch synchronization
    #epoch: Epoch = Epoch.getInstance()
    #synchronizationOffset: number = 0

    callback?: (event: TimerCallbackEvent) => void
    networkSync?: TimerSyncMetadata

    // Promise to monitor for availability
    loaded: Promise<void>

    // we overwrite this with an audioContext if available
    getNow = (): number => performance.timeOrigin + performance.now()

    get options(){
        return this.#options
    }

    get syncOptions(): TimerSyncOptions {
        return normalizeSyncOptions(this.#options)
    }

    get syncMode(): SyncMode {
        return this.syncOptions.mode
    }

    usesSynchronization(): boolean {
        return this.syncMode !== 'off'
    }

    usesNetworkSynchronization(): boolean {
        return NETWORK_SYNC_MODES.includes(this.syncMode)
    }

    get syncReferenceEpochMs(): number | undefined {
        const syncOptions = this.syncOptions
        return syncOptions.mode === 'system-epoch-grid'
            ? syncOptions.referenceEpochMs
            : undefined
    }

    applySyncConfiguration(): void {
        const referenceEpoch = this.syncReferenceEpochMs ?? 0
        this.#epoch.setReferenceEpoch(referenceEpoch)
    }

    /**
     * Can we use this timing method on this device?
     * @returns boolean is the worker available and compatable
     */
    get isRunning():boolean{
        return this.#running
    }
    set isRunning(value: boolean) {
        this.#running = value
    }

    get running(): boolean {
        return this.#running
    }

    /**
     * Can we use this timing method on this device?
     * @returns boolean is the worker available and compatable
     */
    get available(): boolean {
        return this.isCompatible
    }

    get isBypassed():boolean {
        return this.#bypassed
    }
    set isBypassed(value: boolean) {
        this.#bypassed = value
    }

    /**
     * 
     */
    get isActive(): boolean {
        return this.#active
    }

    /**
     * Accurate time in milliseconds
     * @returns number The current time as of now
     */
    get now(): number {
        return this.getNow()
    }

    /** 
     * Time conversion factor
     */
    get clockUnitsToSecondsScale(): number {
        return 0.001
    }

    /**
     * Fetch current bar length in milliseconds
     * @returns number bar length in milliseconds
     */
    get timeBetween(): number {
        return this.period
    }

    /**
     * Amount of time elapsed since startTimer() in seconds
     * @returns number in seconds
     */
    get timeElapsed(): number {
        // How long has elapsed according to audio context
        return ((this.#pausedAt ?? this.now) - this.startTime)// * 0.001 
    }

    /**
     * Fetch whole loop length in milliseconds
     * @returns number length in milliseconds
     */
    get totalTime(): number {
        return this.timePerBar * this.bars
    }

    /**
     * Fetch current bar
     * @returns number current bar
     */
    get bar(): number {
        return this.currentBar
    }

    /**
     * Fetch total bars completed
     * @returns number total bars
     */
    get barsElapsed(): number {
        return Math.floor(this.totalBarsElapsed / this.bars)
    }

    /**
     * Fetch total bar quantity
     * @returns number total bars
     */
    get totalBars(): number {
        return this.bars
    }

    get totalDivisions(): number {
        return this.divisions
    }

    /**
     * Percentage duration of bar progress 0->1
     * @returns number percentage elapsed
     */
    get barProgress(): number {
        return this.currentBar / this.bars
    }

    /**
     * Percentage duration of beat progress 0->1
     * @returns number percentage elapsed
     */
    get beatProgress(): number {
        return this.divisionsElapsed / this.totalDivisions
    }


    // Bar times

    /**
     * Fetch current bar length in milliseconds
     * @returns number bar length in milliseconds
     */
    get timePerBar(): number {
        return this.period * this.divisions
    }

    /**
     * Get the current timing as Beats per minute
     * BPM = 60,000,000 / MicroTempo
     * @returns number BPM
     */
    get BPM(): number {
        return MICROSECONDS_PER_MINUTE / this.timePerBar
    }
    get bpm(): number {
        return this.BPM
    }

    /**
     * Get the duration of one beat (quarternote) 
     * in microseconds
     * @returns number Microtempo
     */
    get quarterNoteDuration(): number {
        return MICROSECONDS_PER_MINUTE / this.bpm
    }

    /**
     * Get the duration of one beat (quarternote) 
     * in seconds
     * @returns number duration in seconds
     */
    get quarterNoteDurationInSeconds(): number {
        return SECONDS_PER_MINUTE / this.bpm
    }

    /**
     * Get the current timing as a Microtempo 
     * @returns number Microtempo
     */
    get microTempo(): number {
        return this.timePerBar * 0.001
    }

    /**
     * Get the current timing in Micros per MIDI clock
     * MicrosPerMIDIClock = MicroTempo / 24 (MIDI 1.0 has 24 divisions)
     * @returns number Micros per MIDI clock
     */
    get microsPerMIDIClock(): number {
        return this.microTempo / this.divisions
    }

    /**
     * How many Ticks are there every second?
     * @returns number ticks per second
     */
    get ticksPerSecond(): number {
        return Ticks.Beat / this.quarterNoteDurationInSeconds
    }

    
    get elapsedSinceLastTick(): number {
        return this.now - this.lastRecordedTime
    }


    get swing(): number {
        return this.swingOffset
    }


    // Positions & booleans
    get isAtStart(): boolean {
        return this.divisionsElapsed === 0
    }
    get isAtStartOfBar(): boolean {
        return this.divisionsElapsed === 0
    }
    get isStartBar(): boolean {
        return this.currentBar === 0
    }
    get isAtMiddleOfBar(): boolean {
        return this.barProgress === 0.5
    }
    
    get isQuarterNote(): boolean {
        return this.beatProgress % 0.25 === 0
    }
    get isHalfNote(): boolean {
        return this.beatProgress % 0.5 === 0
    }
    get isSwungBeat(): boolean {
        return this.swingOffset > 0 && this.divisionsElapsed % 2 === 1
    }
    get isUsingExternalTrigger(): boolean {
        return this.#bypassed
    }

    // Setters ------------------------------------------------------

    /**
     * Fetch current bar
     * @param value bar number
     */
    set bar(value: number | string) {
        this.currentBar = parseInt(String(value))
    }

    /**
     * Allows a user to set the total number of bars
     * @param value How many bars to have in a measure
     */
    set totalBars(value: number) {
        this.bars = value < 1 ? 1 : value > MAX_BARS_ALLOWED ? MAX_BARS_ALLOWED : value
    }

    setBars(value: number): number {
        this.totalBars = value
        return this.bars
    }

    /**
     * Set the current timing using a BPM where 
     * one beat in milliseconds =  60,000 / BPM
     * 
     * @param value Beats per minute
     */
    set BPM(value: number | string) {
        this.timeBetween = 60000 / Math.max(10, parseFloat(String(value)))
    }
    set bpm(value: number | string) {
        this.BPM = value
    }
    set tempo(value: number | string) {
        this.BPM = value
    }

    /**
     * Using a time in milliseconds, set the amount of time between tick and tock
     * @param time Amount of millieconds between ticks
     */
    set timeBetween(time: number) {

        if (this.#running) {
            this.captureTempoChangeAnchor()
        }

        const interval = time / this.divisions
        // we want 16 notes
        this.period = interval

        // TODO
        // FIXME
        // if it is running, stop and restart it?
        //interval = newInterval
        this.postMessage({
            command: CMD_UPDATE,
            interval,
            time: this.now
        })
    }

    /**
     * Passed in the onBeat callback as a variant
     * to determine when the "beat" should occur
     */
    set swing(value: number) {
        this.swingOffset = Math.min(1, Math.max(0, value))
    }

    constructor(options: TimerOptions = DEFAULT_TIMER_OPTIONS, isWorklet?: boolean) {
        this.loaded = Promise.resolve()

        const normalizedSync = normalizeSyncOptions(options)
        options = { ...DEFAULT_TIMER_OPTIONS, ...options, sync: normalizedSync, synch: normalizedSync.mode !== 'off' }
        this.#options = options
        this.applySyncConfiguration()

        const optionKeys = Object.keys(options)
        // Subclass setters such as AudioTimer.BPM can read the active clock.
        // Install supplied contexts before applying any timing-dependent
        // options, regardless of the property order introduced by defaults.
        const contextOptionKeys = optionKeys.filter(key => key === 'contexts' || key === 'audioContext')
        const remainingOptionKeys = optionKeys.filter(key => key !== 'contexts' && key !== 'audioContext')
        const orderedOptionKeys = [...contextOptionKeys, ...remainingOptionKeys]
        // const { contexts, type=AUDIOTIMER_WORKLET_URI, divisions=DIVISIONS, processor=AUDIOTIMER_PROCESSOR_URI} = options

        for (let key of orderedOptionKeys) {
            switch (key) {
                case "audioContext":
                    this.audioContext = options.audioContext as AudioContext
                    this.getNow = (): number => (this.audioContext!.currentTime * 1000)

                    break

                case "contexts":
                    if (options.contexts) {
                        for (let context in options.contexts) {
                            (this as Record<string, unknown>)[context] = options.contexts[context]
                        }
                    }
                    this.getNow = (): number => this.audioContext ? this.audioContext.currentTime * 1000 : performance.now()
                    break

                default:
                    (this as Record<string, unknown>)[key] = (options as Record<string, unknown>)[key]
            }
        }

        // 
        const typeStr = typeof options.type === 'string' ? options.type : ''
        const prefersWorklet = isWorklet ?? (isWorkletTimerType(typeStr) || isFileWorklet(typeStr))

        if (prefersWorklet && this.audioContext) {
            this.loaded = this.setTimingWorklet(
                typeStr,
                options.processor || '',
                this.audioContext
            ) as any
        } else if (prefersWorklet) {
            // Delay backend attachment until an AudioContext is provided or a caller injects a handler.
            this.loaded = Promise.resolve(null as any)
        } else {
            this.loaded = this.setTimingWorker(options.type || '') as any
        }
    }

    /**
     * Set the function that gets called on every divixional tick
     * @param callback Method to call when the timer ticks
     */
    setCallback(callback: (event: TimerCallbackEvent) => void): void {
        this.callback = callback
    }

    /**
     * Allows us to disable the existing route to send our own
     * or to inject them into here 
     * 
     * @param useExternalClock whether to use external clock
     * @returns trigger function
     */
    bypass(useExternalClock: boolean = true): () => void {

        const trigger = (): void => {
            // call callback
            this.externalTrigger()
        }

        if (useExternalClock) {
            if (this.#bypassed) {
                return trigger
            }
            // we want to bypass the worker's work
            this.#bypassed = true
            if (this.#running) {
                // disconnect but don't destroy
                this.disconnectWorker(this.timingWorkHandler, false)
            } else {
            }

        } else {
            if (!this.#bypassed) {
                return trigger
            }
            this.#bypassed = false
            if (this.#running) {
                this.startTimer()
            } else {
            }
        }

        return trigger
    }

    // CONVERSIONS --------------------------------------------------------------------------------

    /**
     * Convert seconds to MIDI clock ticks based on current BPM
     * @param seconds Time in seconds
     * @returns Number of MIDI clock ticks (24 ticks per quarter note)
     */
    secondsToTicks(seconds: number): number {
        return seconds * this.ticksPerSecond
    }

    /**
     * Convert time to ticks using the current tick per second rate
     * @param time in seconds
     * @returns number of ticks
     */
    convertToTicks(time: number): number {
        return time * this.ticksPerSecond
    }

    getSwingDelay(period: number = this.getCurrentPeriodInSeconds()): number {
        return this.swingOffset > 0 ? period * this.swingOffset : 0
    }

    getSwingAdjustment(intervals: number, period: number = this.getCurrentPeriodInSeconds()): number {
        return this.swingOffset > 0 && intervals % 2 === 1 ? this.getSwingDelay(period) : 0
    }

    getExpectedElapsed(intervals: number): number {
        const period = this.getCurrentPeriodInSeconds()
        const relativeIntervals = Math.max(0, intervals - this.#intervalsAtTempoChange)
        const anchorAdjustment = this.getSwingAdjustment(this.#intervalsAtTempoChange, period)
        const intervalAdjustment = this.getSwingAdjustment(intervals, period)

        return this.#expectedAtTempoChange
            + relativeIntervals * period
            + (intervalAdjustment - anchorAdjustment)
    }

    getCurrentPeriodInSeconds(): number {
        return this.timeBetween * 0.001
    }

    updateElapsedScale(timePassed: number): void {
        const localElapsed = this.now - this.startTime
        if (localElapsed > 0 && timePassed > 0) {
            this.#clockTimeToElapsedScale = timePassed / localElapsed
        }
    }

    getTransportElapsedNow(): number {
        if (this.#transportAnchorClockTime < 0) {
            return this.#transportAnchorExpected
        }

        const elapsedSinceAnchor = (this.#pausedAt ?? this.now) - this.#transportAnchorClockTime
        if (elapsedSinceAnchor <= 0) {
            return this.#transportAnchorExpected
        }

        const scale = this.#clockTimeToElapsedScale || this.clockUnitsToSecondsScale

        return this.#transportAnchorExpected + Math.max(0, elapsedSinceAnchor * scale)
    }

    resetTransportTiming(anchorClockTime: number = this.now): void {
        this.#expectedAtTempoChange = 0
        this.#intervalsAtTempoChange = this.#running ? this.#lastTickIntervals : 0
        this.#transportAnchorExpected = 0
        this.#transportAnchorClockTime = anchorClockTime

        if (!this.#running) {
            this.#lastTickIntervals = 0
            this.#clockTimeToElapsedScale = 0
        }
    }

    captureTempoChangeAnchor(anchorClockTime: number = this.now): void {
        if (!this.#running) {
            return
        }

        // Keep transport time continuous at the moment of change; only future intervals
        // should use the new period reported by the worker/worklet.
        const transportElapsed = this.getTransportElapsedNow()
        this.#expectedAtTempoChange = transportElapsed
        this.#intervalsAtTempoChange = this.#lastTickIntervals
        this.#transportAnchorExpected = transportElapsed
        this.#transportAnchorClockTime = anchorClockTime
    }

    createTick(
        intervals: number,
        timePased: number,
        audioTiming: AudioTickTiming = {}
    ): void {
        // A disconnected AudioWorklet can still deliver queued ticks and CMD_UPDATE
        // can wake it again. External clocks must be the sole source of pulses.
        if (this.#bypassed) return
        const timeBetweenPeriod = this.getCurrentPeriodInSeconds()
        // Expected time stamp
        const expected = this.getExpectedElapsed(intervals)
        // How long has elapsed according to our worker
        const timePassed = timePased + this.#workerElapsedOffset
        // how much spill over the expected timestamp is there
        const lag = this.swingOffset > 0 ? timePassed - expected : timePassed % timeBetweenPeriod
        // should be 0 if the timer is working...
        const drift = timePassed - this.timeElapsed
        // deterministic intervals not neccessary
        const level = Math.floor(timePassed / this.timeBetween)
        // elapsed should === time
        if (this.#running) {
            this.#lastTickIntervals = intervals
            this.#transportAnchorExpected = expected
            this.#transportAnchorClockTime = this.now
            this.updateElapsedScale(timePassed)
            this.onTick(timePassed, expected, drift, level, intervals, lag, true, audioTiming)
        }
    }

    // WORKLET ------------------------------------------------------------------------------------

    /**
     * Set the worklet as the main timing mechanism
     * @param type URL or identifier
     * @param processor processor name
     * @param audioContext audio context
     * @returns the worklet node
     */
    async setTimingWorklet(type: string, processor: string, audioContext?: AudioContext): Promise<TimingHandler> {

        let wasRunning = this.#running

        // destroy any existing worklet
        if (this.timingWorkHandler) {
            await this.unsetTimingWorker()
        }

        try {
            // Check if type is a valid timer type string
            if (isValidTimerType(type) && type !== TIMER_TYPE_AUDIO_WORKLET) {
                // If it's a valid worker type (not worklet), delegate to setTimingWorker
                const workerClass = resolveTimerType(type as TimerType)
                if (workerClass) {
                    return await this.setTimingWorker(workerClass)
                }
            }

            // Dynamically import the worklet based on type parameter
            const createWorklet = type === TIMER_TYPE_ELASTIC_AUDIO_WORKLET
                ? (await import('./worklets/elastic-timing.audioworklet')).createElasticTimingWorklet
                : (await import('./worklets/timing.audioworklet')).createTimingWorklet
            // Ensure we have an AudioContext
            if (!audioContext) {
                throw new Error('AudioContext is required for AudioWorklet')
            }

            this.timingWorkHandler = await createWorklet(audioContext)
            this.timingWorkHandler = await createWorklet(audioContext)
            this.isCompatible = true

            // console.error(type, "timer.audioworklet", {module, audioContext}, this.timingWorker ) 
            if (wasRunning) {
                // Pass the stored callback to ensure it's re-registered with the new worklet
                await this.startTimer(this.callback)
            }
            return this.timingWorkHandler
        } catch (error) {
            this.isCompatible = false
            throw error
        }
    }

    // WORKER ------------------------------------------------------------------------------------

    /**
     * Load in the Worker URI
     * @param type URL or identifier
     * @returns the worker instance
     */
    async loadTimingWorker(type: string | WorkerWrapper): Promise<Worker> {
        if (typeof Worker === 'undefined') {
            throw new Error('Worker is not available in this environment')
        }
        
        try {
            // Handle Worker factory from URL-based imports (default for production)
            if (typeof type === 'function') {
                return type()
            }
            // Fallback: Handle URL strings for flexibility
            else if (typeof type === 'string') {
                // Ensure absolute URLs for GitHub Pages compatibility
                let workerUrl = type
                if (!workerUrl.startsWith('http') && !workerUrl.startsWith('blob:')) {
                    const baseUrl = `${window.location.origin}/`
                    workerUrl = new URL(type, baseUrl).href
                }
                return new Worker(workerUrl, { type: 'module' })
            }
            else {
                throw new Error(`Invalid worker type: expected function or string, got ${typeof type}`)
            }
        } catch (error) {
            throw error
        }
    }

    /**
     * In the future, we may be able to pass offlineAudioContext to a worker
     * and at that point, we can finally tie in the actual timing by using the 
     * context as the global clock!
     * NB. We NOW CAN! User the setTimingWorklet instead :)
     * @param type URL, identifier, or timer type string constant
     * @returns the worker instance or null if failed
     */
    async setTimingWorker(type: string | WorkerWrapper): Promise<Worker | null> {
        try {

            let wasRunning = this.#running

            // destroy any existing worker
            if (this.timingWorkHandler) {
                await this.unsetTimingWorker()
            }

            // Resolve timer type string to worker class if needed
            let workerType: string | WorkerWrapper = type
            if (typeof type === 'string' && isValidTimerType(type)) {
                const resolved = resolveTimerType(type as TimerType)
                if (resolved) {
                    workerType = resolved
                }
            }

            this.timingWorkHandler = await this.loadTimingWorker(workerType)

            if (!this.timingWorkHandler) {
                throw Error("Timing Worker failed to load url: type:" + type)
            }


            if (wasRunning) {
                // Pass the stored callback to ensure it's re-registered with the new worker
                await this.startTimer(this.callback)
            } else {
            }

            return this.timingWorkHandler

        } catch (error) {

            this.isCompatible = false
        }
        return null
    }

    /**
     * Unregister any Worker set
     * @returns boolean success
     */
    async unsetTimingWorker(): Promise<boolean> {
        // TODO: clone the methods into new worker
        await this.stopTimer()
        const handler = this.timingWorkHandler
        if (handler) {
            if ('terminate' in handler) {
                (handler as Worker).terminate()
            }
            (handler as any).onmessage = null;
            (handler as any).onerror = null
        }
        this.timingWorkHandler = null
        return true
    }

    /**
     * Switch to a different timing worker/worklet type
     * Safely handles switching even if the timer is currently running
     * @param timerType Timer type string constant (e.g., TIMER_TYPE_AUDIO_CONTEXT)
     * @param audioContext Optional AudioContext for worklet types
     * @returns Success status
     * @throws Error if the timer type is invalid or switching fails
     */
    async switchTimerType(timerType: TimerType | string, audioContext?: AudioContext): Promise<boolean> {
        try {
            // Validate the timer type
            if (!isValidTimerType(timerType)) {
                throw new Error(`Invalid timer type: ${timerType}. Must be one of: ${Object.values(TIMER_TYPES).join(', ')}`)
            }

            const wasRunning = this.#running

            // Stop the timer if it's running
            if (wasRunning) {
                await this.stopTimer()
            }

            // Switch to the new timer type
            if (isWorkletTimerType(timerType)) {
                // Audio worklet requires special handling
                if (!audioContext) {
                    throw new Error('AudioContext is required when switching to audio-worklet timer type')
                }
                await this.setTimingWorklet(timerType, '', audioContext)
            } else {
                // Regular workers
                await this.setTimingWorker(timerType)
            }

            // Restart the timer if it was running before
            if (wasRunning) {
                await this.startTimer()
            } else {
            }

            return true

        } catch (error) {
            this.isCompatible = false
            throw error
        }
    }

    // SHARED WORKER / WORKLET CDE ------------------------------------------------------------------------------------

    /**
     * Add a worker or worklet into the pipeline
     * and monitor it's events and messages
     * @param worker the worker instance
     */
    connectWorker(worker: TimingHandler): void {

        if (!worker) {
            throw new Error("Timing Worker was not defined - please check paths " + worker);
        }

        // now hook into our worker bee and watch for timing changes
        (worker as any).onmessage = (e: MessageEvent<any>) => {

            const time = this.now;
            const data = e.data;

            switch (data.event) {
                case EVENT_READY:
                    break;

                case EVENT_STARTING:
                    // save start time
                    this.startTime = time - this.#resumeElapsed;
                    this.#pausedAt = null;
                    this.#transportAnchorClockTime = time;
                    this.#running = true;
                    break;

                case EVENT_TICK:
                    // const timeBetweenPeriod = this.timeBetween * 0.001
                    // // How many ticks have occured yet
                    // const intervals = data.intervals
                    // // Expected time stamp
                    // const expected = intervals * timeBetweenPeriod

                    // // How long has elapsed according to our worker
                    // const timePassed = data.time
                    // // how much spill over the expected timestamp is there
                    // const lag = timePassed % timeBetweenPeriod
                    // // should be 0 if the timer is working...
                    // const drift = timePassed - this.timeElapsed
                    // // deterministic intervals not neccessary
                    // const level = Math.floor(timePassed / this.timeBetween)
                    // // elapsed should === time
                    // this.onTick(timePassed,expected, drift, level, intervals, lag)

                    // timingWorker.postMessage({command:CMD_UPDATE, time:currentTime, interval})
                    this.createTick(data.intervals, data.time, {
                        contextTimeSeconds: data.contextTimeSeconds,
                        scheduledContextTimeSeconds: data.scheduledContextTimeSeconds,
                        audioFrame: data.audioFrame,
                        sampleRate: data.sampleRate,
                    });
                    break;

                default:
            }
        };

        // Worker Loading Error!
        (worker as any).onerror = (event: ErrorEvent) => {
            const errorMsg = event.message || event.filename || 'Unknown error'
            const errorDetails = {
                error: errorMsg,
                filename: event.filename,
                lineno: event.lineno,
                colno: event.colno,
                stack: event.error?.stack,
                time: this.now
            }
            if (worker) {
                (worker as any).postMessage(errorDetails)
            }
        }
    }

    postMessage(payload: Record<string, unknown>): void {
        this.timingWorkHandler && (this.timingWorkHandler as any).postMessage(payload)
    }

    /**
     * Disconnect the worker from the timer
     * @param worker the worker to disconnect
     * @param setStopped whether to set isRunning to false
     */
    disconnectWorker(worker: TimingHandler, setStopped: boolean = true): void {
        if (!worker) return
        (worker as any).onmessage = (e: MessageEvent<any>) => {
            const data = e.data as Record<string, unknown>
            switch (data.event) {
                // Clean up
                case EVENT_STOPPING:
                    // destroy contexts and unsubscribe from events
                    if (setStopped) {
                        this.#running = false
                    }
                    break
            }
        }

        (worker as any).postMessage({
            command: CMD_STOP,
            time: this.now
        })
    }

    //--------------------------------------------------

    /**
     * Reset the timer and start from the beginning
     */
    resetTimer(): void {
        this.currentBar = 0
        this.totalBarsElapsed = 0
        this.divisionsElapsed = 0
        this.startTime = this.now
        this.#resumeElapsed = 0
        this.#workerElapsedOffset = 0
        this.#pausedAt = this.#running ? null : this.now
        this.resetTransportTiming()
    }

    async start(callback?: (event: TimerCallbackEvent) => void): Promise<{ time: number; interval: number; worker: TimingHandler }> {
        return this.startTimer(callback ?? this.callback)
    }

    async stop(): Promise<{ currentTime: number; worker: TimingHandler }> {
        return this.stopTimer()
    }
    async toggle(): Promise<boolean> {
        return this.toggleTimer(this.callback)
    }

    /**
     * Starts the timer and begins events being dispatched
     * 
     * @param callback optional callback to call on each tick
     * @param options optional options
     * @returns object with current time and worker/worklet
     */
    async startTimer(
        callback?: (event: TimerCallbackEvent) => void,
        options: Record<string, unknown> = {}
    ): Promise<{ time: number; interval: number; worker: TimingHandler }> {

        if (options) {
            const nextOptions = { ...this.#options, ...options } as TimerOptions
            const normalizedSync = normalizeSyncOptions(options as TimerOptions, this.syncOptions)
            this.#options = {
                ...nextOptions,
                sync: normalizedSync,
                synch: normalizedSync.mode !== 'off'
            }
            this.applySyncConfiguration()
        }

        await this.loaded

        const currentTime = this.now

        if (!this.#running) {
            // Worker interval numbers restart, but the musical transport resumes.
            this.#resumeElapsed = this.#pausedAt === null ? 0 : this.timeElapsed
            const expected = this.#pausedAt === null ? 0 : this.getTransportElapsedNow()
            this.#workerElapsedOffset = this.#resumeElapsed * (this.#clockTimeToElapsedScale || this.clockUnitsToSecondsScale)
            this.#expectedAtTempoChange = expected
            this.#intervalsAtTempoChange = 0
            this.#lastTickIntervals = 0
            this.#transportAnchorExpected = expected
            this.#transportAnchorClockTime = currentTime
        }

        if (callback) {
            this.setCallback(callback)
        }

        // Calculate synchronization offset if enabled
        if (this.usesSynchronization()) {
            this.#synchronizationOffset = this.#epoch.synchronizeMetronome(this.period)
        } else {
            this.#synchronizationOffset = 0
        }

        // if we are using an external clock
        // we try and determine the tempo ourselves
        if (this.#bypassed) {
            this.startTime = currentTime - this.#resumeElapsed
            this.#pausedAt = null
            this.#running = true
            return {
                time: currentTime,
                interval: -1,
                worker: null
            }
        }

        this.connectWorker(this.timingWorkHandler)

        const payload = {
            command: CMD_START,
            time: currentTime,
            interval: this.period,
            accurateTiming: this.options.accurate,
            synchronizationOffset: this.#synchronizationOffset
        }

        // send command to worker... options
        this.postMessage(payload)

        return {
            time: currentTime,
            interval: this.period,
            worker: this.timingWorkHandler
        }
    }

    /**
     * Stops the timer and prevents events being dispatched
     * @returns object with current time and worker/worklet
     */
    async stopTimer(): Promise<{ currentTime: number; worker: TimingHandler }> {

        await this.loaded

        const currentTime = this.now
        if (this.#running) {
            this.#pausedAt = currentTime
            this.#resumeElapsed = this.timeElapsed
        }
        this.#running = false
        // cancel the thing thrugh the workers first
        // cancel any scheduled quie noises
        this.disconnectWorker(this.timingWorkHandler)

        

        return {
            currentTime,
            worker: this.timingWorkHandler
        }
    }

    /**
     * Start the timer if it is paused...
     * or stop the timer if it is running
     * 
     * @param callback optional callback to call on each tick
     * @param options optional options
     * @returns boolean indicating if timer is running
     */
    async toggleTimer(
        callback?: (event: TimerCallbackEvent) => void,
        options: Record<string, unknown> = {}
    ): Promise<boolean> {
        if (this.#bypassed) {
            // we are using an external timer!
            return this.#running
        }
        if (!this.#running) {
            await this.startTimer(callback, options)
        } else {
            await this.stopTimer()
        }
        return this.#running
    }

    /**
     * Tap a tempo into the system
     * requires 3 taps to set the tempo
     * @returns the detected tempo in BPM, or -1 if not enough taps
     */
    tapTempo(): number {
        const tempo = tapTempoQuick()
        if (tempo > -1) {
            this.BPM = tempo
            return tempo
        }
        return -1
    }

    /**
     * Get the current synchronization offset
     * @returns the offset in milliseconds to the next global tick
     */
    getSynchronizationOffset(): number {
        return this.#synchronizationOffset
    }

    /**
     * Get the current tick number on the global metronome grid
     * @returns the tick number
     */
    getGlobalTickNumber(): number {
        this.applySyncConfiguration()
        return this.#epoch.getTickNumber(this.period)
    }

    /**
     * Enable or disable synchronization for this timer
     * @param enabled whether synchronization should be enabled
     */
    setSynchronized(enabled: boolean): void {
        const sync: TimerSyncOptions = enabled
            ? (this.syncMode === 'off'
                ? { ...DEFAULT_SYNC_OPTIONS }
                : this.syncOptions)
            : {
                mode: 'off',
                join: this.syncOptions.join,
                beatsPerBar: this.syncOptions.beatsPerBar
            }

        this.#options.sync = sync
        this.#options.synch = enabled
        this.applySyncConfiguration()
    }

    /**
     * Check if this timer is synch to the global grid
     * @returns whether synchronization is enabled
     */
    isSynchronized(): boolean {
        return this.usesSynchronization()
    }

    /**
     * Use an external device to send clock signals to and through this timer
     * such as the MIDI clock signal
     * @param advance whether to advance the divisions counter
     */
    externalTrigger(advance: boolean = true): void {
        // How long has elapsed according to our clock
        const timestamp = this.now
        const previousRecordedExternalTime = this.lastRecordedExternalTime
        this.lastRecordedExternalTime = timestamp

        // work out the BPOM from the clock...
        // const BPM = convertPeriodToBPM( period * 24 )

        // const period = tapTempo(true, 10000, 3)
        const elapsedSinceLastClock = previousRecordedExternalTime > 0
            ? (timestamp - previousRecordedExternalTime) * this.clockUnitsToSecondsScale
            : this.getCurrentPeriodInSeconds()
        const elapsedTimestamp = timestamp * this.clockUnitsToSecondsScale
        // Expected time stamp
        const expected = this.divisionsElapsed * elapsedSinceLastClock
        // how much spill over the expected timestamp is there
        const lag = elapsedSinceLastClock > 0 ? elapsedTimestamp % elapsedSinceLastClock : 0
        // should be 0 if the timer is working...
        const drift = elapsedTimestamp - expected
        // deterministic intervals not neccessary
        const level = elapsedSinceLastClock > 0 ? Math.floor(elapsedTimestamp / elapsedSinceLastClock) : 0

        // console.log("MIDI CLOCK", BPM, period, elapsedSinceLastClock, timestamp )

        if (this.#running && this.#bypassed) {
            this.onTick(elapsedSinceLastClock, expected, drift, level, this.divisionsElapsed, lag, advance)
        }
    }


    /**
     * Repeat previous clock tick but do not advance
     */
    retrigger(): void {
        this.externalTrigger(false)
        // this.createTick( data.intervals, data.time )			
    }

    /** Apply an absolute network pulse without deriving musical position from packet arrival. */
    networkTick(tick: number, audioTiming: AudioTickTiming): void {
        if (!this.#running || !this.#bypassed || !Number.isSafeInteger(tick) || tick < 0) return
        this.divisionsElapsed = tick % this.divisions
        this.totalBarsElapsed = Math.floor(tick / this.divisions)
        this.currentBar = this.totalBarsElapsed % this.bars
        this.lastRecordedExternalTime = this.now
        const scheduled = audioTiming.scheduledContextTimeSeconds ?? this.now * this.clockUnitsToSecondsScale
        this.onTick(scheduled, scheduled, 0, tick, tick, 0, false, audioTiming)
    }

    // EVENTS =============================================================================

    /**
     * EVENT: Timer is available
     */
    onAvailable = (): void => {
        // console.info("Timer is available")
    }

    /**
     * EVENT: Timer is unavailable
     */
    onUnavailable = (): void => {
        // console.error("Timer is unavailable")
    }

    /**
     * Occurs 24 times per beat
     * Call the callback with internal flags
     * @param timePassed time passed since start
     * @param expected expected time
     * @param drift timing drift
     * @param level timing level
     * @param intervals number of intervals
     * @param lag timing lag
     */
    onTick(
        timePassed: number,
        expected: number,
        drift: number = 0,
        level: number = 0,
        intervals: number = 0,
        lag: number = 0,
        advanceDivisions: boolean = true,
        audioTiming: AudioTickTiming = {}
    ): void {

        this.lastRecordedTime = timePassed;

        // check if bar has completed
        if (advanceDivisions) {
            if (++this.divisionsElapsed >= this.divisions) {
                ++this.totalBarsElapsed
                this.currentBar = (this.currentBar + 1) % this.bars
                this.divisionsElapsed = 0
            }
        }
        this.callback && this.callback({
            bar: this.currentBar,
            bars: this.totalBars,
            divisionsElapsed: this.divisionsElapsed,
            barsElapsed: this.barsElapsed,
            elapsed: this.timeElapsed,
            //performance
            timePassed,
            expected,
            drift,
            level,
            intervals,
            lag,
            ...audioTiming,
            sync: this.networkSync ?? {
                mode: this.syncMode,
                status: this.usesNetworkSynchronization() ? 'probing' : (this.usesSynchronization() ? 'locked' : 'free'),
                join: this.syncOptions.join,
                referenceEpochMs: this.syncReferenceEpochMs
            }
        })
    }
}


